SELECT "t8"."order_number", "t8"."line_no", "t8"."item", "t8"."unit_price", "t8"."list_price", 'hold_sales' AS "route", 'price_differences' AS "context"
FROM (SELECT "order_number0" AS "order_number", "line_no0" AS "line_no", "item", "unit_price", "price" AS "list_price"
        FROM (SELECT "t1"."order_number", "t1"."line_no", "t1"."item", "t1"."unit_price", "t1"."customer", "t1"."channel", "t1"."placed_date", "t5"."order_number" AS "order_number0", "t5"."line_no" AS "line_no0", "t5"."price"
                FROM (SELECT "sales_line"."order_number", "sales_line"."line_no", "sales_line"."item", "sales_line"."unit_price", "t0"."customer", "t0"."channel", "t0"."placed_date"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t0"
                            INNER JOIN "sales_line" ON "t0"."order_number" = "sales_line"."order_number") AS "t1"
                    INNER JOIN (SELECT "t4"."order_number", "t4"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                        FROM (SELECT "sales_line0"."order_number", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."unit_price", "t3"."customer", "t3"."channel", "t3"."placed_date"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t3"
                                    INNER JOIN "sales_line" AS "sales_line0" ON "t3"."order_number" = "sales_line0"."order_number") AS "t4"
                            LEFT JOIN "customer_price" ON "t4"."item" = "customer_price"."item" AND "t4"."customer" = "customer_price"."customer" AND "t4"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t4"."placed_date" <= "customer_price"."valid_to")
                            LEFT JOIN "price_list" ON "t4"."item" = "price_list"."item" AND "t4"."channel" = "price_list"."channel" AND "t4"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t4"."placed_date" <= "price_list"."valid_to")) AS "t5" ON "t1"."order_number" = "t5"."order_number" AND "t1"."line_no" = "t5"."line_no") AS "t6"
        WHERE "t6"."price" IS NULL OR ABS("t6"."unit_price" - "t6"."price") > :tolerance) AS "t8"
    INNER JOIN (SELECT "order_number"
        FROM (SELECT "t36"."order_number", "t36"."customer", "t36"."channel", "t36"."fulfilling_warehouse", "t36"."value", "t36"."placed_date", "t36"."state", COALESCE("t36"."n_short", 0) AS "n_short", COALESCE("t36"."n_price", 0) AS "n_price", COALESCE("t42"."n_due", 0) AS "n_due"
                FROM (SELECT "t24"."order_number", "t24"."customer", "t24"."channel", "t24"."fulfilling_warehouse", "t24"."value", "t24"."placed_date", "t24"."state", "t24"."n_short", "t35"."n_price"
                        FROM (SELECT "t10"."order_number", "t10"."customer", "t10"."channel", "t10"."fulfilling_warehouse", "t10"."value", "t10"."placed_date", "t10"."state", "t23"."n_short"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t10"
                                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                        FROM (SELECT "t18"."order_number", "t18"."customer", "t18"."channel", "t18"."fulfilling_warehouse", "t18"."value", "t18"."placed_date", "t18"."state", "t18"."line_no", "t18"."item", "t18"."quantity", "t18"."unit_price", "t18"."ext_sales_price", "t18"."warehouse", "t18"."sold_date", "t18"."customer0", "t18"."channel0", "t18"."as_of_date", "t18"."quantity_on_hand", "t18"."_ttrp_g_n8_0", "t18"."_ttrp_g_n8_1", "t19"."warehouse" AS "warehouse0", "t19"."from_date", "t19"."to_date", "t19"."reason", COALESCE("t18"."quantity_on_hand", 0) AS "on_hand", "t19"."warehouse" IS NOT NULL AS "outage"
                                                FROM (SELECT "t13"."order_number", "t13"."customer", "t13"."channel", "t13"."fulfilling_warehouse", "t13"."value", "t13"."placed_date", "t13"."state", "t13"."line_no", "t13"."item", "t13"."quantity", "t13"."unit_price", "t13"."ext_sales_price", "t13"."warehouse", "t13"."sold_date", "t13"."customer0", "t13"."channel0", "t17"."as_of_date", "t17"."quantity_on_hand", "t17"."_ttrp_g_n8_0", "t17"."_ttrp_g_n8_1"
                                                        FROM (SELECT "t12"."order_number", "t12"."customer", "t12"."channel", "t12"."fulfilling_warehouse", "t12"."value", "t12"."placed_date", "t12"."state", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."quantity", "sales_line1"."unit_price", "sales_line1"."ext_sales_price", "sales_line1"."warehouse", "sales_line1"."sold_date", "sales_line1"."customer" AS "customer0", "sales_line1"."channel" AS "channel0"
                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                        FROM "order"
                                                                        WHERE "state" IN ('held', 'placed')) AS "t12"
                                                                    INNER JOIN "sales_line" AS "sales_line1" ON "t12"."order_number" = "sales_line1"."order_number") AS "t13"
                                                            LEFT JOIN (SELECT "t14"."as_of_date", "t14"."item", "t14"."warehouse", "t14"."quantity_on_hand", "t14"."_ttrp_g_n8_0", "t14"."_ttrp_g_n8_1"
                                                                FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1"
                                                                        FROM "inventory") AS "t14"
                                                                    INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", MAX("as_of_date") AS "_ttrp_latest_n8"
                                                                        FROM "inventory"
                                                                        GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t16" ON "t14"."_ttrp_g_n8_0" = "t16"."_ttrp_g_n8_0" AND "t14"."_ttrp_g_n8_1" = "t16"."_ttrp_g_n8_1" AND "t14"."as_of_date" = "t16"."_ttrp_latest_n8") AS "t17" ON "t13"."item" = "t17"."item" AND "t13"."warehouse" = "t17"."warehouse") AS "t18"
                                                    LEFT JOIN (SELECT *
                                                        FROM "warehouse_outage"
                                                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t19" ON "t18"."warehouse" = "t19"."warehouse") AS "t20"
                                        WHERE "t20"."outage" OR "t20"."on_hand" < "t20"."quantity"
                                        GROUP BY "order_number") AS "t23" ON "t10"."order_number" = "t23"."order_number") AS "t24"
                            LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                                FROM (SELECT "t27"."order_number", "t27"."line_no", "t27"."item", "t27"."unit_price", "t27"."customer", "t27"."channel", "t27"."placed_date", "t31"."order_number" AS "order_number0", "t31"."line_no" AS "line_no0", "t31"."price"
                                        FROM (SELECT "sales_line2"."order_number", "sales_line2"."line_no", "sales_line2"."item", "sales_line2"."unit_price", "t26"."customer", "t26"."channel", "t26"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t26"
                                                    INNER JOIN "sales_line" AS "sales_line2" ON "t26"."order_number" = "sales_line2"."order_number") AS "t27"
                                            INNER JOIN (SELECT "t30"."order_number", "t30"."line_no", COALESCE("customer_price0"."price", "price_list0"."price") AS "price"
                                                FROM (SELECT "sales_line3"."order_number", "sales_line3"."line_no", "sales_line3"."item", "sales_line3"."unit_price", "t29"."customer", "t29"."channel", "t29"."placed_date"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t29"
                                                            INNER JOIN "sales_line" AS "sales_line3" ON "t29"."order_number" = "sales_line3"."order_number") AS "t30"
                                                    LEFT JOIN "customer_price" AS "customer_price0" ON "t30"."item" = "customer_price0"."item" AND "t30"."customer" = "customer_price0"."customer" AND "t30"."placed_date" >= "customer_price0"."valid_from" AND ("customer_price0"."valid_to" IS NULL OR "t30"."placed_date" <= "customer_price0"."valid_to")
                                                    LEFT JOIN "price_list" AS "price_list0" ON "t30"."item" = "price_list0"."item" AND "t30"."channel" = "price_list0"."channel" AND "t30"."placed_date" >= "price_list0"."valid_from" AND ("price_list0"."valid_to" IS NULL OR "t30"."placed_date" <= "price_list0"."valid_to")) AS "t31" ON "t27"."order_number" = "t31"."order_number" AND "t27"."line_no" = "t31"."line_no") AS "t32"
                                WHERE "t32"."price" IS NULL OR ABS("t32"."unit_price" - "t32"."price") > :tolerance
                                GROUP BY "order_number0") AS "t35" ON "t24"."order_number" = "t35"."order_number") AS "t36"
                    LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                        FROM (SELECT "t38"."order_number", "t38"."customer", "t38"."channel", "t38"."fulfilling_warehouse", "t38"."value", "t38"."placed_date", "t38"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t38"
                                    INNER JOIN "invoice" ON "t38"."customer" = "invoice"."customer") AS "t39"
                        WHERE "t39"."status" = 'open' AND "t39"."due" < :as_of
                        GROUP BY "order_number") AS "t42" ON "t36"."order_number" = "t42"."order_number") AS "t43"
        WHERE "t43"."n_short" > 0 OR "t43"."n_price" > 0
        GROUP BY "order_number") AS "t46" ON "t8"."order_number" = "t46"."order_number"
